<template>
  <main><NavBar/><section class="studio">
    <header><div><span class="eyebrow">Private workspace</span><h1>Admin Studio</h1><p>Manage channel identities and publish as any editorial channel.</p></div><div class="stats"><span><b>{{overview.users}}</b> users</span><span><b>{{overview.posts}}</b> blugs</span></div></header>
    <nav class="tabs" aria-label="Admin sections"><button :class="{active:tab==='channels'}" @click="tab='channels'">Channels</button><button :class="{active:tab==='system'}" @click="tab='system'">System</button></nav>
    <div v-if="tab==='channels'" class="channel-grid">
      <aside class="channel-list"><label class="search">⌕<input v-model="query" aria-label="Search channels" placeholder="Search channels"></label><button v-for="channel in filteredChannels" :key="channel.id" class="channel-row" :class="{selected:selected?.id===channel.id}" @click="selectChannel(channel)"><img :src="channel.profile_image_url||'/Default_pfp.svg'" alt=""><span><b>{{channel.full_name}}</b><small>@{{channel.chatter_name}} · {{channel.post_count}} blugs</small></span></button></aside>
      <div v-if="selected" class="editor">
        <div class="identity-card"><div class="cover" :style="{backgroundImage:`url(${selected.header_image_url||'/Default_Header.svg'})`}"><label class="image-button">Change header<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="uploadChannelImage($event,'header')"></label></div><div class="identity"><div class="avatar-wrap"><img :src="selected.profile_image_url||'/Default_pfp.svg'" alt="Channel profile"><label class="avatar-button" title="Change profile picture">+<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="uploadChannelImage($event,'profile')"></label></div><div><h2>{{selected.full_name}}</h2><p>@{{selected.chatter_name}}</p></div><span class="locked">Channel · no login</span></div></div>
        <form class="panel fields" @submit.prevent="saveChannel"><div class="panel-title"><div><h3>Channel details</h3><p>Changes appear everywhere this channel is shown.</p></div><button class="primary" :disabled="busy">{{busy?'Saving…':'Save changes'}}</button></div><label>Name<input v-model="channelForm.full_name" maxlength="100" required></label><label>Handle<div class="handle"><span>@</span><input v-model="channelForm.chatter_name" maxlength="40" required></div></label><label class="wide">Description<textarea v-model="channelForm.about_me" maxlength="500" rows="3"></textarea><small>{{channelForm.about_me.length}}/500</small></label></form>
        <section class="panel"><div class="panel-title"><div><h3>Channel blugs</h3><p>Edit existing blugs or add a new one.</p></div><button class="primary" @click="newPost">+ New blug</button></div>
          <form v-if="postEditor" class="post-form" @submit.prevent="savePost"><div class="form-heading"><b>{{postEditor.id?'Edit blug':'New channel blug'}}</b><button type="button" class="quiet" @click="postEditor=null">Close</button></div><label>Title<input v-model="postEditor.title" maxlength="180" required></label><label>Topic<input v-model="postEditor.categories" maxlength="80" placeholder="History, Sports, Culture…"></label><label>Blug text<textarea v-model="postEditor.content" rows="12" required></textarea></label><div class="post-actions"><label v-if="postEditor.id" class="upload-cover">Add / replace cover<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="uploadPostCover"></label><span v-else>Save first, then add its cover.</span><button class="primary" :disabled="busy">{{busy?'Saving…':postEditor.id?'Update blug':'Publish blug'}}</button></div></form>
          <div class="post-list"><article v-for="post in selected.posts" :key="post.id"><img :src="post.header_image_url||'/Default_Header.svg'" alt=""><div><span>{{post.categories||'Uncategorized'}}</span><h4>{{post.title}}</h4><small>Updated {{formatDate(post.updated_at)}}</small></div><button @click="editPost(post)">Edit</button></article></div>
        </section>
      </div><div v-else class="empty">No channel found.</div>
    </div>
    <div v-else class="system"><h2>System records</h2><h3>Pending recovery approvals</h3><p v-if="!pendingRecoveries.length">No recoveries are waiting for approval.</p><article v-for="user in pendingRecoveries" :key="`pending-${user.id}`"><span><b>{{user.full_name}}</b> · @{{user.chatter_name}}</span><button :disabled="busy" @click="approveRecovery(user.id)">Approve</button></article><h3>Users</h3><article v-for="user in users" :key="user.id"><span>@{{user.chatter_name}} · {{user.role}}<small v-if="user.recovery_status==='pending'"> · Pending approval</small></span><button v-if="user.id!==me&&!user.id.startsWith('channel-')" @click="removeUser(user.id)">Delete</button></article><h3>Notifications</h3><article v-for="item in notifications" :key="item.id"><span>{{item.message}}</span><button @click="removeNotification(item.id)">Delete</button></article></div>
    <p v-if="message" class="toast" role="status">{{message}}</p>
  </section></main>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import NavBar from'./NavBar.vue';import{adminApproveRecovery,adminCreateChannelPost,adminDeleteNotification,adminDeleteUser,adminUpdateChannel,adminUpdateChannelPost,getAdminOverview,listAdminChannels,listAdminNotifications,listAdminUsers,type AdminChannel}from'../api/admin';import{uploadImage}from'../api/uploads';import{authStore}from'../stores/auth';import type{LocalPost,LocalUser}from'../api/types';import type{LocalNotification}from'../api/notifications';
const overview=reactive({users:0,posts:0,notifications:0,supportCases:0}),users=ref<LocalUser[]>([]),notifications=ref<LocalNotification[]>([]),channels=ref<AdminChannel[]>([]),selected=ref<AdminChannel|null>(null),tab=ref<'channels'|'system'>('channels'),query=ref(''),busy=ref(false),message=ref(''),me=authStore.user.value?.id;const channelForm=reactive({full_name:'',chatter_name:'',about_me:''});const postEditor=ref<(Pick<LocalPost,'title'|'content'|'categories'>&{id?:string})|null>(null);const filteredChannels=computed(()=>channels.value.filter(c=>`${c.full_name} ${c.chatter_name}`.toLowerCase().includes(query.value.toLowerCase())));const selectChannel=(c:AdminChannel)=>{selected.value=c;Object.assign(channelForm,{full_name:c.full_name,chatter_name:c.chatter_name,about_me:c.about_me||''});postEditor.value=null};const load=async(keep?:string)=>{Object.assign(overview,await getAdminOverview());channels.value=(await listAdminChannels()).channels;users.value=(await listAdminUsers()).users;notifications.value=(await listAdminNotifications()).notifications;const channel=channels.value.find(c=>c.id===(keep||selected.value?.id))||channels.value[0];if(channel)selectChannel(channel)};const run=async(fn:()=>Promise<void>,ok:string)=>{busy.value=true;message.value='';try{await fn();message.value=ok;setTimeout(()=>message.value='',2600)}catch(e){message.value=e instanceof Error?e.message:'Something went wrong.'}finally{busy.value=false}};const saveChannel=()=>selected.value&&run(async()=>{await adminUpdateChannel(selected.value!.id,{...channelForm});await load(selected.value!.id)},'Channel updated.');const uploadChannelImage=(e:Event,p:'header'|'profile')=>{const f=(e.target as HTMLInputElement).files?.[0];if(f&&selected.value)run(async()=>{await uploadImage(f,p,undefined,selected.value!.id);await load(selected.value!.id)},`${p==='header'?'Header':'Profile picture'} updated.`)};const newPost=()=>postEditor.value={title:'',categories:'',content:''};const editPost=(p:LocalPost)=>postEditor.value={id:p.id,title:p.title,categories:p.categories||'',content:p.content};const savePost=()=>selected.value&&postEditor.value&&run(async()=>{const d=postEditor.value!;if(d.id)await adminUpdateChannelPost(selected.value!.id,d.id,d);else{const r=await adminCreateChannelPost(selected.value!.id,d);postEditor.value={...d,id:r.post.id}}await load(selected.value!.id)},postEditor.value.id?'Blug updated.':'Blug published.');const uploadPostCover=(e:Event)=>{const f=(e.target as HTMLInputElement).files?.[0];if(f&&postEditor.value?.id&&selected.value)run(async()=>{await uploadImage(f,'header',postEditor.value!.id);await load(selected.value!.id)},'Cover updated.')};const removeUser=async(id:string)=>{if(confirm('Delete this user?')){await adminDeleteUser(id);await load()}};const removeNotification=async(id:string)=>{await adminDeleteNotification(id);await load()};const formatDate=(v:string)=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v));onMounted(()=>load());
const pendingRecoveries=computed(()=>users.value.filter(user=>user.recovery_status==='pending'));
const approveRecovery=(id:string)=>run(async()=>{await adminApproveRecovery(id);await load()},'Recovery approved.');
</script>
